function StepDatas({ answers, setAnswers, onNext, onBack }) {
  const flexLevel = answers.flexLevel || "fixed";
  const FLEX_OPTS = [{ id: "fixed", label: "Datas fixas" }, { id: "some", label: "Posso variar alguns dias" }, { id: "flex", label: "Bastante flexibilidade" }];

  return (
    <div style={{ background: BG, minHeight: "100vh", display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
      <WizardTopBar step={3} onExit={onBack} />
      <div style={{ display: "flex", flexDirection: "column", gap: 56, alignItems: "center", padding: "40px 120px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 12, alignItems: "center", textAlign: "center" }}>
          <p style={{ fontFamily: FONT_DISPLAY, fontWeight: 700, fontSize: 36, color: TEXT, margin: 0 }}>Quando você quer viajar?</p>
          <p style={{ fontFamily: FONT_BODY, fontSize: 16, color: BODY, width: 600, margin: 0 }}>Escolha as datas e diga o quanto pode flexibilizar</p>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 20, alignItems: "center" }}>
          <p style={{ fontFamily: FONT_MONO, fontSize: 14, color: GREEN, textTransform: "uppercase", margin: 0 }}>Datas de viagem</p>
          <div style={{ display: "flex", gap: 12, width: 800 }}>
            <div style={{ flex: 1, background: "#fff", border: `1px solid ${BORDER}`, display: "flex", gap: 12, alignItems: "center", padding: "16px 24px", borderRadius: 8 }}>
              <Calendar size={20} color={TEXT} />
              <input
                type="date"
                value={answers.dateStart || ""}
                min={new Date().toISOString().split("T")[0]}
                onChange={(e) => {
                  const newStart = e.target.value;
                  setAnswers((a) => ({
                    ...a,
                    dateStart: newStart,
                    dateEnd: a.dateEnd && a.dateEnd < newStart ? "" : a.dateEnd,
                  }));
                }}
                style={{ flex: 1, border: "none", outline: "none", fontFamily: FONT_DISPLAY, fontWeight: 700, fontSize: 16, color: TEXT, background: "transparent" }}
              />
            </div>
            <div style={{ flex: 1, background: "#fff", border: `1px solid ${BORDER}`, display: "flex", gap: 12, alignItems: "center", padding: "16px 24px", borderRadius: 8 }}>
              <Calendar size={20} color={TEXT} />
              <input
                type="date"
                value={answers.dateEnd || ""}
                min={answers.dateStart || new Date().toISOString().split("T")[0]}
                onChange={(e) => setAnswers((a) => ({ ...a, dateEnd: e.target.value }))}
                style={{ flex: 1, border: "none", outline: "none", fontFamily: FONT_DISPLAY, fontWeight: 700, fontSize: 16, color: TEXT, background: "transparent" }}
              />
            </div>
          </div>
        </div>
        <div style={{ height: 1, background: BORDER, width: 800 }} />
        <div style={{ display: "flex", flexDirection: "column", gap: 20, alignItems: "center" }}>
          <p style={{ fontFamily: FONT_MONO, fontSize: 14, color: GREEN, textTransform: "uppercase", margin: 0 }}>Flexibilidade</p>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 12, justifyContent: "center", width: 800 }}>
            {FLEX_OPTS.map((o) => {
              const active = flexLevel === o.id;
              return (
                <div key={o.id} onClick={() => setAnswers((a) => ({ ...a, flexLevel: o.id }))} style={{ background: active ? GREEN_BG : "#fff", border: `1.5px solid ${active ? GREEN : BORDER}`, padding: "16px 24px", borderRadius: 8, cursor: "pointer" }}>
                  <p style={{ fontFamily: FONT_DISPLAY, fontWeight: 700, fontSize: 16, color: active ? GREEN : TEXT, margin: 0 }}>{o.label}</p>
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <WizardBottomBar onBack={onBack} onNext={onNext} />
    </div>
  );
}

